session_start();require_once '../shared/config.php';requireLogin('vendor','login.php');$vendorId=$_SESSION['vendor_id'];$storeName=$_SESSION['vendor_name'];$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$description=trim($_POST['description']??'');$category=trim($_POST['category']??'');$quality=$_POST['quality']??'Good';$rentDay=floatval($_POST['rent_per_day']??0);$rentHour=floatval($_POST['rent_per_hour']??0);$late=floatval($_POST['late_charge_per_day']??0);if(!$name||!$rentDay){$error='Item name and daily rent are required.';}else{$imagePath='';if(!empty($_FILES['item_image']['name'])){$dir='../uploads/items/';if(!is_dir($dir))mkdir($dir,0777,true);$ext=strtolower(pathinfo($_FILES['item_image']['name'],PATHINFO_EXTENSION));$allowed=['jpg','jpeg','png','gif','webp'];if(!in_array($ext,$allowed))$error='Invalid image format.';elseif($_FILES['item_image']['size']>5*1024*1024)$error='Image too large. Max 5MB.';else{$imagePath=uniqid('item_').'.'.$ext;if(!move_uploaded_file($_FILES['item_image']['tmp_name'],$dir.$imagePath)){$error='Failed to upload image.';$imagePath='';}}}if(!$error){$db=getDB();$st=$db->prepare("INSERT INTO items(vendor_id,name,description,category,quality,rent_per_hour,rent_per_day,late_charge_per_day,image_path) VALUES(?,?,?,?,?,?,?,?,?)");$st->execute([$vendorId,$name,$description,$category,$quality,$rentHour,$rentDay,$late,$imagePath]);$success="Item "$name" added successfully!";}}}
